CREATE TABLE IF NOT EXISTS migrations(version text PRIMARY KEY);
CREATE TABLE users(id uuid PRIMARY KEY,email text UNIQUE NOT NULL,name text NOT NULL,password text NOT NULL,verified boolean NOT NULL DEFAULT false);
CREATE TABLE sessions(hash text PRIMARY KEY,user_id uuid REFERENCES users ON DELETE CASCADE,csrf text NOT NULL,expires timestamptz NOT NULL);
CREATE INDEX sessions_user ON sessions(user_id);
CREATE TABLE tokens(hash text PRIMARY KEY,user_id uuid REFERENCES users ON DELETE CASCADE,kind text CHECK(kind IN ('verify','reset')),expires timestamptz NOT NULL);
CREATE TABLE mail_queue(id bigserial PRIMARY KEY,recipient text NOT NULL,subject text NOT NULL,body text NOT NULL,sent boolean NOT NULL DEFAULT false);
CREATE TABLE rate_limits(key text PRIMARY KEY,count int NOT NULL,expires timestamptz NOT NULL);
CREATE TABLE games(id uuid PRIMARY KEY,name text NOT NULL,code text UNIQUE NOT NULL,max_players int CHECK(max_players BETWEEN 2 AND 32),speed int CHECK(speed IN (1,2,5)),last_tick timestamptz NOT NULL DEFAULT now());
CREATE TABLE participants(game_id uuid REFERENCES games,user_id uuid REFERENCES users,country text NOT NULL,state jsonb NOT NULL,PRIMARY KEY(game_id,user_id),UNIQUE(game_id,country));
CREATE TABLE commands(game_id uuid REFERENCES games,user_id uuid REFERENCES users,id uuid,body_hash text NOT NULL,response jsonb NOT NULL,PRIMARY KEY(game_id,user_id,id));
CREATE TABLE events(id bigserial PRIMARY KEY,game_id uuid REFERENCES games,user_id uuid REFERENCES users,payload jsonb NOT NULL,created timestamptz DEFAULT now());
CREATE INDEX events_replay ON events(game_id,id);
CREATE TABLE alliances(id uuid PRIMARY KEY,game_id uuid REFERENCES games,name text NOT NULL);
CREATE TABLE alliance_members(alliance_id uuid REFERENCES alliances,user_id uuid REFERENCES users,game_id uuid REFERENCES games,role text CHECK(role IN ('leader','advisor','member')),PRIMARY KEY(alliance_id,user_id),UNIQUE(game_id,user_id));
CREATE TABLE invitations(id uuid PRIMARY KEY,alliance_id uuid REFERENCES alliances,recipient uuid REFERENCES users,status text NOT NULL DEFAULT 'pending');
CREATE TABLE messages(id bigserial PRIMARY KEY,game_id uuid REFERENCES games,sender uuid REFERENCES users,recipient uuid REFERENCES users,alliance_id uuid REFERENCES alliances,body text NOT NULL,created timestamptz DEFAULT now());
CREATE TABLE meetings(id uuid PRIMARY KEY,alliance_id uuid REFERENCES alliances,title text NOT NULL,proposal text NOT NULL,deadline timestamptz NOT NULL);
CREATE TABLE votes(meeting_id uuid REFERENCES meetings,user_id uuid REFERENCES users,choice text CHECK(choice IN ('yes','no','abstain')),PRIMARY KEY(meeting_id,user_id));
INSERT INTO migrations VALUES('001_core');
